class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        pre, suf = p.split('*')
        n = len(s)
        for i in range(n + 1):
            for j in range(i, n + 1):
                if s[i:i + len(pre)] == pre and s[max(i, j - len(suf)):j] == suf and j - i >= len(pre) + len(suf):
                    return True
        return False

