class Solution {
public:
    bool hasMatch(string s, string p) {
        int star = p.find('*');
        string pre = p.substr(0, star), suf = p.substr(star + 1);
        int n = s.size();
        for (int i = 0; i <= n; i++) {
            for (int j = i; j <= n; j++) {
                if ((int)s.size() - 1 < j - 1) break;
                if (j - i >= (int)pre.size() + (int)suf.size()
                    && s.compare(i, pre.size(), pre) == 0
                    && (suf.empty() || s.compare(j - suf.size(), suf.size(), suf) == 0))
                    return true;
            }
        }
        return false;
    }
};

