public:
    bool hasMatch(string s, string p) {
        int star = p.find('*');
        string pre = p.substr(0, star), suf = p.substr(star + 1);
        size_t i = s.find(pre);
        if (i == string::npos) return false;
        if (suf.empty()) return true;
        return s.find(suf, i + pre.size() - 1) != string::npos;
    }
};

